/* Editable photo records and album states, entirely local to this browser. */
(() => {
  const UI=window.PrototypeUI,R=window.PrototypeRecords,page=location.pathname.split('/').pop().slice(0,7),id=new URLSearchParams(location.search).get('id'),screen=document.querySelector('.screen');
  const all=()=>R.all().filter(r=>r.type==='photo'),nickname=()=>UI.read('dujia-profile',{}).nickname||'小满';
  function missing(){screen.classList.add('prototype-photo-missing');const box=UI.components.state({kind:'error',title:'这张照片已经不在了',message:'内容可能已被删除，回到相册可以继续浏览或添加照片。',action:'返回相册',onAction:()=>UI.go('m03-p10.html',{force:true})});box.classList.add('prototype-photo-state');screen.append(box);}
  const goAlbum=()=>UI.go(all().length?'m03-p10.html':'m03-p09.html',{force:true});
  document.querySelector('.back')?.addEventListener('click',()=>UI.back(['m03-p09','m03-p10'].includes(page)?'m03-p02.html':'m03-p10.html'));
  if(page==='m03-p09'){
    if(all().length){UI.go('m03-p10.html',{replace:true,force:true});return;}
    document.querySelectorAll('.primary,.picker button').forEach(b=>b.onclick=()=>UI.go('m03-p11.html'));
  }
  if(page==='m03-p11'){
    const existing=id?R.find(id,'photo'):null;if(id&&!existing){missing();return;}
    const form=document.querySelector('#photo-form'),file=document.querySelector('#file'),preview=document.querySelector('#selected'),hit=document.querySelector('#photo-hit');
    let image=existing?.image||null,sampleImage=!!existing?.sampleImage,reading=false,saving=false;
    form.elements.caption.value=existing?.caption||'';form.elements.caption.maxLength=1000;form.elements.tag.value=existing?.tags?.join('、')||'';form.elements.tag.maxLength=100;
    form.elements.date.value=existing?.date||new Date().toLocaleDateString('en-CA');form.elements.date.readOnly=true;
    if(existing)form.elements.visibility.value=existing.visibility;else form.elements.visibility.value=window.PrototypePreferences?.privacy().scope==='仅自己可见'?'private':'shared';if(window.PrototypePreferences?.privacy().shared===false){const sharedOption=form.querySelector('[name=visibility][value=shared],option[value=shared]');if(sharedOption)sharedOption.disabled=true;if(!existing)form.elements.visibility.value='private';}
    function paint(){hit.classList.toggle('prototype-photo-blank',!image);hit.classList.toggle('prototype-photo-sample',sampleImage);preview.style.display=image&&!sampleImage?'block':'none';if(image&&!sampleImage)preview.src=image;hit.setAttribute('aria-label',image?'更换照片':'选择照片');}
    paint();const values=()=>JSON.stringify({caption:form.elements.caption.value,date:form.elements.date.value,tags:form.elements.tag.value,visibility:form.elements.visibility.value,image});
    const leave=UI.guard(form,{fallback:existing?R.route(existing):'m03-p10.html',value:values});
    hit.onclick=()=>file.click();file.addEventListener('change',async()=>{const chosen=file.files[0];if(!chosen)return;reading=true;hit.setAttribute('aria-busy','true');try{image=await R.readImage(chosen,'photo-image');sampleImage=false;paint();}catch(error){UI.toast(error.message+'，原照片仍保留','error');file.value='';}finally{reading=false;hit.removeAttribute('aria-busy');}});
    form.elements.date.onclick=async()=>{const label=document.createElement('label');label.textContent='照片日期';const input=document.createElement('input');input.type='date';input.value=form.elements.date.value;input.setAttribute('aria-label','选择照片日期');label.append(input);const action=await UI.sheet({title:'选择照片日期',content:label,actions:[{label:'使用这个日期',value:'apply'}]});if(action==='apply'){if(!input.value||new Date(input.value+'T00:00:00')>new Date()){UI.toast('请选择有效的过去日期','error');return;}form.elements.date.value=input.value;}};
    document.querySelector('#add-tag').onclick=async()=>{const label=document.createElement('label');label.textContent='标签，用顿号分隔';const input=document.createElement('input');input.type='text';input.maxLength=100;input.value=form.elements.tag.value;input.setAttribute('aria-label','编辑照片标签');label.append(input);const action=await UI.sheet({title:'照片标签',content:label,actions:[{label:'使用这些标签',value:'apply'}]});if(action==='apply')form.elements.tag.value=input.value;};
    async function save(button){
      if(saving)return;if(reading){UI.toast('照片正在读取，请稍候');return;}if(!image){UI.toast('请先选择照片','error');hit.focus();return;}
      const tags=[...new Set(form.elements.tag.value.split(/[、,，]/).map(t=>t.trim()).filter(Boolean))];if(tags.length>5||tags.some(t=>t.length>12)){UI.fieldError(form.elements.tag,'最多5个标签，每个不超过12字');form.elements.tag.focus();return;}
      const date=form.elements.date.value;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(new Date(date).getTime())||new Date(date+'T00:00:00')>new Date()){UI.fieldError(form.elements.date,'请选择有效的过去日期');return;}
      saving=true;const peer=button.id==='done'?form.querySelector('.submit'):document.querySelector('#done');peer.disabled=true;
      await UI.busy(button,'保存中…',()=>{if(UI.failNext('photo-save'))throw new Error('照片没有保存成功，请重试');const caption=form.elements.caption.value.trim(),item={...existing,id:existing?.id||'photo-'+crypto.randomUUID(),type:'photo',status:'published',title:caption.slice(0,60)||'这一刻的回忆',caption,body:caption,date,tags,visibility:form.elements.visibility.value,image,sampleImage,author:existing?.author||nickname(),createdAt:existing?.createdAt||Date.now(),updatedAt:Date.now(),comments:existing?.comments||[]};if(!R.put(item))return false;leave.commit();UI.toast('照片已保存','success');sessionStorage.removeItem('dujia-photo-album-state');return existing?UI.go(R.route(item),{force:true}):goAlbum();});saving=false;peer.disabled=false;
    }
    form.addEventListener('submit',e=>{e.preventDefault();save(form.querySelector('.submit'));});document.querySelector('#done').onclick=()=>save(document.querySelector('#done'));form.dataset.prototypeReady='true';
  }
  if(page==='m03-p10'){
    if(!all().length){UI.go('m03-p09.html',{replace:true,force:true});return;}
    const grid=document.querySelector('.grid');grid.classList.add('prototype-photo-grid');grid.setAttribute('aria-label','照片列表');document.querySelector('.month').textContent='珍藏的瞬间';
    let state;try{state=JSON.parse(sessionStorage.getItem('dujia-photo-album-state')||'null');}catch{}let tab=state?.tab||0,visibility=state?.visibility||'all';const tabs=[...document.querySelectorAll('[role=tab]')],persist=()=>sessionStorage.setItem('dujia-photo-album-state',JSON.stringify({tab,visibility}));
    function render(){grid.replaceChildren();tabs.forEach((b,i)=>{b.classList.toggle('active',i===tab);b.setAttribute('aria-selected',String(i===tab));});const photos=all().filter(r=>(tab!==1||r.visibility==='shared')&&(tab!==2||r.tags?.includes('旅行'))&&(visibility==='all'||r.visibility===visibility));if(!photos.length){const box=document.createElement('div');box.className='prototype-photo-empty';const title=document.createElement('h2');title.textContent='没有符合条件的照片';const clear=document.createElement('button');clear.textContent='清除筛选';clear.onclick=()=>{tab=0;visibility='all';persist();render();};box.append(title,clear);grid.append(box);return;}
      for(const item of photos){const button=document.createElement('button');button.className='prototype-photo-card';const img=document.createElement('img');img.src=item.image;img.alt='';if(item.sampleImage)img.className='prototype-photo-sample-thumb';img.onerror=()=>{img.hidden=true;button.classList.add('prototype-photo-image-error');};const title=document.createElement('span');title.textContent=item.title;button.append(img,title);button.onclick=()=>UI.go(R.route(item));grid.append(button);}}
    tabs.forEach((b,i)=>b.onclick=()=>{tab=i;persist();render();});document.querySelector('.add').onclick=()=>UI.go('m03-p11.html');document.querySelector('#filter').onclick=async()=>{const select=document.createElement('select');select.setAttribute('aria-label','照片可见范围');for(const[v,label]of[['all','全部'],['shared','共同可见'],['private','仅自己可见']]){const option=document.createElement('option');option.value=v;option.textContent=label;select.append(option);}select.value=visibility;const action=await UI.sheet({title:'筛选照片',content:select,actions:[{label:'应用筛选',value:'apply'},{label:'清除筛选',value:'clear'}]});if(action){visibility=action==='clear'?'all':select.value;if(action==='clear')tab=0;persist();render();}};
    const refresh=document.createElement('button');refresh.type='button';refresh.className='prototype-photo-refresh';refresh.textContent='↻';refresh.setAttribute('aria-label','刷新相册');screen.append(refresh);let loading=false;
    async function load(){if(loading)return;loading=true;refresh.disabled=true;grid.replaceChildren();grid.setAttribute('aria-busy','true');const text=document.createElement('p');text.textContent='正在打开相册…';text.setAttribute('role','status');grid.append(text);await new Promise(resolve=>setTimeout(resolve,400));grid.removeAttribute('aria-busy');loading=false;refresh.disabled=false;if(UI.failNext('photo-load')){grid.replaceChildren();const box=document.createElement('div');box.className='prototype-photo-empty';const title=document.createElement('h2');title.textContent='相册暂时打不开';const retry=document.createElement('button');retry.textContent='重试加载';retry.onclick=load;box.append(title,retry);grid.append(box);}else render();}refresh.onclick=load;load();
  }
  if(page==='m03-p12'){
    let item=R.find(id||'sample-photo-1','photo');if(!item){missing();return;}
    document.querySelector('.title').textContent=item.title;const caption=document.querySelector('.caption');caption.textContent=item.caption;caption.tabIndex=0;caption.setAttribute('role','region');caption.setAttribute('aria-label','照片心情');document.querySelector('.meta').textContent=`${item.author} · ${item.date} · ${item.visibility==='private'?'仅自己可见':'共同可见'}`;
    const photo=document.querySelector('.photo');if(!item.sampleImage){photo.style.background='#fffaf0';const img=document.createElement('img');img.src=item.image;img.alt=item.title;photo.append(img);img.onerror=()=>{img.hidden=true;photo.textContent='照片暂时无法显示';const retry=document.createElement('button');retry.textContent='重试图片';retry.onclick=()=>{photo.replaceChildren(img);img.hidden=false;img.src=item.image;};photo.append(retry);};}
    document.querySelector('.edit').onclick=()=>UI.go('m03-p11.html?id='+encodeURIComponent(item.id));
    const more=document.createElement('button');more.id='more';more.className='prototype-photo-more';more.textContent='•••';more.setAttribute('aria-label','更多操作');screen.append(more);more.onclick=async()=>{const action=await UI.sheet({title:'照片操作',actions:[{label:'删除照片',value:'delete',danger:true}]});if(action!=='delete'||!await UI.modal({title:'删除这张照片？',message:'照片和其中的留言将一起删除。',confirm:'确认删除',cancel:'取消'}))return;UI.busy(more,'删除中…',()=>{if(UI.failNext('photo-delete'))throw new Error('删除没有完成，请重试');if(!R.remove(item.id))return false;return goAlbum();});};
    const form=document.querySelector('#message'),input=document.querySelector('#reply'),comments=document.querySelector('[aria-label=留言]');comments.classList.add('prototype-photo-comments');input.maxLength=300;if(window.PrototypePreferences?.privacy().replies===false){input.disabled=true;form.querySelector('[type=submit]').disabled=true;input.placeholder='新的回应已关闭';}comments.replaceChildren();
    if(item.visibility==='private'){screen.classList.add('prototype-photo-private');form.hidden=true;comments.hidden=true;document.querySelector('.comments-title').textContent='这张照片仅自己可见';document.querySelector('.comments-art').style.background='#fffaf0';}
    else{
      function paint(){comments.replaceChildren();if(!item.comments?.length)comments.textContent='还没有留言，留下一句温柔的话吧';for(const reply of item.comments||[]){const article=document.createElement('article');const author=document.createElement('b');author.textContent=reply.author;const text=document.createElement('p');text.textContent=reply.text;article.append(author,text);comments.append(article);}}paint();
      document.querySelector('#emoji').onclick=()=>{input.value=(input.value+' ❤️').slice(0,300);input.focus();};form.addEventListener('submit',e=>{e.preventDefault();if(window.PrototypePreferences?.privacy().replies===false){UI.toast('新的回应已关闭');return;}const text=input.value.trim();if(!text){UI.fieldError(input,'请先写一句话');input.focus();return;}UI.busy(form.querySelector('[type=submit]'),'发送中…',()=>{if(UI.failNext('photo-comment'))throw new Error('留言未发送成功，请重试');const latest=R.find(item.id,'photo');if(!latest){UI.toast('这张照片已被删除','error');return false;}const next={...latest,comments:[...(latest.comments||[]),{id:crypto.randomUUID(),author:nickname(),text,createdAt:Date.now()}]};if(!R.put(next))return false;item=next;input.value='';paint();return true;});});form.dataset.prototypeReady='true';
    }
  }
})();
